    mockGenerateContentStream.mockResolvedValue({
      stream: streamFrom([{candidates: [{content: {parts: [{text: 'ok'}]}, finishReason: 'STOP'}]}]),
    });

    const provider = createVertexProvider({
      ...defaultConfig,
      location: 'eu',
      apiEndpoint: 'aiplatform.eu.rep.googleapis.com',
